// Orders created before the `deliveries` table existed have no rows there.
// The schedule board and driver app both read from `deliveries`, so give
// every such order exactly one delivery mirroring its own driver/date/status
// — never re-split a legacy order, that would rewrite real delivery history.
function backfillDeliveries() {
  const orphans = db.prepare(`
    SELECT o.id, o.quantity, o.status, o.driver_id, o.scheduled_date, o.delivered_at
    FROM orders o LEFT JOIN deliveries d ON d.order_id = o.id
    WHERE d.id IS NULL
  `).all();
  if (!orphans.length) return;
  for (const o of orphans) {
    let status = 'unscheduled';
    let driverId = null, scheduledDate = null, slotIndex = null, deliveredAt = null;
    if (o.status === 'cancelled') {
      status = 'cancelled';
    } else if (o.status === 'delivered' || o.status === 'invoiced') {
      status = 'delivered'; driverId = o.driver_id; scheduledDate = o.scheduled_date; deliveredAt = o.delivered_at;
    } else if (o.status === 'out_for_delivery') {
      status = 'out_for_delivery'; driverId = o.driver_id; scheduledDate = o.scheduled_date; slotIndex = 0;
    } else if (o.driver_id && o.scheduled_date) {
      status = 'scheduled'; driverId = o.driver_id; scheduledDate = o.scheduled_date; slotIndex = 0;
    }
    db.prepare(
      `INSERT INTO deliveries (order_id, sequence, quantity, driver_id, scheduled_date, slot_index, status, delivered_at) VALUES (?, 1, ?, ?, ?, ?, ?, ?)`
    ).run(o.id, o.quantity, driverId, scheduledDate, slotIndex, status, deliveredAt);
  }
}

// One-time: give every existing delivery row a dollar `amount` (its
// proportional share of its order's total_amount, split by quantity, with
// the last load absorbing the rounding remainder so the loads sum exactly
// to the order total). Only fills rows where amount is still NULL, so it
// never overwrites a manual override made after this has already run once.
function backfillDeliveryAmounts() {
  const orders = db.prepare(`
    SELECT DISTINCT o.id, o.total_amount
    FROM orders o
    JOIN deliveries d ON d.order_id = o.id AND d.amount IS NULL
  `).all();
  for (const o of orders) {
    const loads = db.prepare(
      `SELECT id, quantity FROM deliveries WHERE order_id = ? AND status != 'cancelled' ORDER BY sequence`
    ).all(o.id);
    if (!loads.length) continue;
    const totalQty = loads.reduce((s, l) => s + l.quantity, 0) || 1;
    let assigned = 0;
    loads.forEach((l, i) => {
      let amt;
      if (i === loads.length - 1) {
        amt = Math.round((o.total_amount - assigned) * 100) / 100;
      } else {
        amt = Math.round((o.total_amount * (l.quantity / totalQty)) * 100) / 100;
        assigned += amt;
      }
      db.prepare(`UPDATE deliveries SET amount = ? WHERE id = ?`).run(amt, l.id);
    });
    const cancelled = db.prepare(
      `SELECT id, quantity FROM deliveries WHERE order_id = ? AND status = 'cancelled' AND amount IS NULL`
    ).all(o.id);
    for (const l of cancelled) {
      const amt = Math.round((o.total_amount * (l.quantity / totalQty)) * 100) / 100;
      db.prepare(`UPDATE deliveries SET amount = ? WHERE id = ?`).run(amt, l.id);
    }
  }
}

// One-time: move each order's COD payment-collected record (recorded before
// per-delivery tracking existed) onto that order's first non-cancelled
// delivery, so already-collected payments aren't silently lost. Guarded to
// only copy when the target delivery doesn't already show payment_collected.
function backfillDeliveryPayments() {
  const paidOrders = db.prepare(`
    SELECT id, payment_collected_method, payment_collected_amount, payment_collected_at
    FROM orders WHERE payment_collected = 1
  `).all();
  for (const o of paidOrders) {
    const target = db.prepare(
      `SELECT id, payment_collected FROM deliveries WHERE order_id = ? AND status != 'cancelled' ORDER BY sequence LIMIT 1`
    ).get(o.id);
    if (!target || target.payment_collected) continue;
    db.prepare(
      `UPDATE deliveries SET payment_collected = 1, payment_collected_method = ?, payment_collected_amount = ?, payment_collected_at = ? WHERE id = ?`
    ).run(o.payment_collected_method, o.payment_collected_amount, o.payment_collected_at, target.id);
  }
}

function run(sql, params = []) { return db.prepare(sql).run(...params); }
function get(sql, params = []) { return db.prepare(sql).get(...params); }
function all(sql, params = []) { return db.prepare(sql).all(...params); }

function getSetting(key, fallback = null) {
  const row = get('SELECT value FROM settings WHERE key = ?', [key]);
  return row && row.value !== '' && row.value !== null ? row.value : fallback;
}
function setSetting(key, value) {
  const existing = get('SELECT key FROM settings WHERE key = ?', [key]);
  if (existing) run('UPDATE settings SET value = ? WHERE key = ?', [value, key]);
  else run('INSERT INTO settings (key, value) VALUES (?, ?)', [key, value]);
}

