const OPEN_ORDER_STATUS_LABELS = {
  new: 'New', scheduled: 'Scheduled', out_for_delivery: 'Out for Delivery', delivered: 'Delivered (awaiting invoice)',
};

// A snapshot of every order still needing action — not yet invoiced,
// cancelled, or refused — for a quick printable "what's still open" report.
function buildOpenOrdersReportPdf(orders, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  const pageBottom = 60;
  let y;

  function header(title) {
    doc.filledRect(0, PDF_PAGE_HEIGHT - 70, PDF_PAGE_WIDTH, 70, 0.93);
    doc.text(marginX, PDF_PAGE_HEIGHT - 40, companyName, { font: 'F2', size: 18 });
    doc.text(marginX, PDF_PAGE_HEIGHT - 58, title, { size: 11 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 40, `Generated ${formatEasternDate(new Date())}`, { size: 9 });
    return PDF_PAGE_HEIGHT - 95;
  }

  y = header('Open Orders Report');

  const counts = {};
  let totalValue = 0;
  orders.forEach((o) => { counts[o.status] = (counts[o.status] || 0) + 1; totalValue += Number(o.total_amount || 0); });

  doc.text(marginX, y, 'Summary', { font: 'F2', size: 12 });
  y -= 18;
  doc.text(marginX, y, `Total open orders: ${orders.length}`, { size: 10 });
  doc.text(marginX + 220, y, `Total value: $${totalValue.toFixed(2)}`, { size: 10 });
  y -= 16;
  Object.keys(OPEN_ORDER_STATUS_LABELS).forEach((status) => {
    if (!counts[status]) return;
    doc.text(marginX, y, `${OPEN_ORDER_STATUS_LABELS[status]}: ${counts[status]}`, { size: 10 });
    y -= 14;
  });
  y -= 10;

  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;

  const cols = [
    { label: 'Order #', x: marginX, w: 85 },
    { label: 'Status', x: marginX + 85, w: 110 },
    { label: 'Customer', x: marginX + 195, w: 80 },
    { label: 'Material', x: marginX + 275, w: 55 },
    { label: 'Qty', x: marginX + 330, w: 28 },
    { label: 'Driver', x: marginX + 358, w: 50 },
    { label: 'Sched.', x: marginX + 408, w: 40 },
    { label: 'Amount', x: marginX + 448, w: 40 },
  ];
  function tableHeader() {
    cols.forEach((c) => doc.text(c.x, y, c.label, { font: 'F2', size: 9 }));
    y -= 6;
    doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
    y -= 13;
  }
  tableHeader();
  if (!orders.length) {
    doc.text(marginX, y, 'Nothing open right now — every order is invoiced, cancelled, or refused.', { size: 10 });
  }
  orders.forEach((o) => {
    const statusLines = wrapPdfText(OPEN_ORDER_STATUS_LABELS[o.status] || o.status || '', 20);
    const rowHeight = Math.max(12, statusLines.length * 10);
    if (y - rowHeight < pageBottom) {
      doc.newPage();
      y = header('Open Orders Report (cont.)');
      tableHeader();
    }
    doc.text(cols[0].x, y, o.order_number || '', { size: 8 });
    statusLines.forEach((line, i) => doc.text(cols[1].x, y - i * 10, line, { size: 8 }));
    doc.text(cols[2].x, y, String(o.customer_name || '').slice(0, 16), { size: 8 });
    doc.text(cols[3].x, y, String(o.material_name || '').slice(0, 12), { size: 8 });
    doc.text(cols[4].x, y, `${o.quantity}${o.unit ? ' ' + o.unit : ''}`, { size: 8 });
    doc.text(cols[5].x, y, String(o.driver_name || 'Unassign.').slice(0, 10), { size: 8 });
    doc.text(cols[6].x, y, o.scheduled_date ? formatDateOnlyShort(o.scheduled_date) : '—', { size: 8 });
    doc.text(cols[7].x, y, `$${Number(o.total_amount || 0).toFixed(2)}`, { size: 8 });
    y -= rowHeight;
  });

  return doc.toBuffer();
}

// A printable per-driver rundown of one day's stops — one page per driver.
function buildDriverDayReportPdf(dateStr, deliveries, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  const dateObj = new Date(`${dateStr}T00:00:00`);
  const dateLabel = isNaN(dateObj.getTime())
    ? dateStr
    : dateObj.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  function pageHeader(driverName, truckLabel) {
    let py = PDF_PAGE_HEIGHT - 60;
    doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
    doc.text(marginX, py, companyName, { font: 'F2', size: 20 });
    py -= 22;
    doc.text(marginX, py, 'Driver Schedule', { font: 'F1', size: 12 });
    py = PDF_PAGE_HEIGHT - 110;
    doc.text(marginX, py, `${driverName}${truckLabel ? ' — ' + truckLabel : ''}`, { font: 'F2', size: 14 });
    doc.text(PDF_PAGE_WIDTH - 230, py, dateLabel, { size: 10 });
    return py - 26;
  }

  const byDriver = new Map();
  const unassigned = [];
  deliveries.forEach((d) => {
    if (!d.driver_id) { unassigned.push(d); return; }
    if (!byDriver.has(d.driver_id)) byDriver.set(d.driver_id, { name: d.driver_name || 'Driver', truck: d.driver_truck, items: [] });
    byDriver.get(d.driver_id).items.push(d);
  });
  const groups = Array.from(byDriver.values()).sort((a, b) => a.name.localeCompare(b.name));
  if (unassigned.length) groups.push({ name: 'Unassigned', truck: null, items: unassigned });

  if (!groups.length) {
    const y = pageHeader('No Deliveries', null);
    doc.text(marginX, y, 'Nothing scheduled for this day.', { size: 11 });
    return doc.toBuffer();
  }

  groups.forEach((g, gi) => {
    if (gi > 0) doc.newPage();
    let y = pageHeader(g.name, g.truck);
    doc.text(marginX, y, `${g.items.length} stop${g.items.length === 1 ? '' : 's'} today`, { font: 'F2', size: 10 });
    y -= 22;
    const items = g.items.slice().sort((a, b) => (a.slot_index ?? 99) - (b.slot_index ?? 99));
    items.forEach((d, i) => {
      if (y < 100) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
      const asap = d.requested_window === 'ASAP' ? '  (ASAP)' : '';
      const load = d.total_deliveries > 1 ? ` (load ${d.sequence}/${d.total_deliveries})` : '';
      doc.text(marginX, y, `${i + 1}. ${d.delivery_address}${asap}`, { font: 'F2', size: 11 });
      y -= 15;
      doc.text(marginX + 14, y, `${d.quantity} ${d.unit} ${d.material_name} for ${d.customer_name} — Order #${d.order_number}${load}`, { size: 10 });
      y -= 15;
      if (d.customer_phone) { doc.text(marginX + 14, y, `Phone: ${d.customer_phone}`, { size: 9 }); y -= 13; }
      if (d.order_notes) {
        wrapPdfText(`Note: ${d.order_notes}`, 90).forEach((line) => { doc.text(marginX + 14, y, line, { size: 9 }); y -= 12; });
      }
      y -= 10;
    });
  });

  return doc.toBuffer();
}

// ---------------------------------------------------------------------------
// Twilio (raw REST calls, no SDK) — SMS order alerts
// ---------------------------------------------------------------------------
function twilioConfigured() { return Boolean(TWILIO_ACCOUNT_SID && TWILIO_AUTH_TOKEN && TWILIO_FROM_NUMBER); }
async function sendSms(to, body) {
  if (!twilioConfigured()) throw new Error('Twilio is not configured.');
  const url = `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`;
  const params = new URLSearchParams({ To: to, From: TWILIO_FROM_NUMBER, Body: body });
  const auth = Buffer.from(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`).toString('base64');
  const resp = await fetch(url, { method: 'POST', headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/x-www-form-urlencoded' }, body: params.toString() });
  const json = await resp.json();
  if (!resp.ok) throw new Error(json.message || 'Twilio send failed');
  return json;
}
async function broadcastSms(recipients, body) {
  const results = await Promise.allSettled(recipients.map((r) => sendSms(r.phone, body)));
  results.forEach((r, i) => { if (r.status === 'rejected') console.error(`SMS to ${recipients[i].name} (${recipients[i].phone}) failed:`, r.reason?.message || r.reason); });
  return results;
}

// ---------------------------------------------------------------------------
// ClickSend (raw REST calls, no SDK) — primary SMS channel. Carrier
// email-to-text gateways (AT&T/Verizon/T-Mobile) were shut down
// industry-wide in 2025 to fight spam abuse, so a real SMS API is needed.
// ---------------------------------------------------------------------------
function clicksendConfigured() { return Boolean(CLICKSEND_USERNAME && CLICKSEND_API_KEY); }
function clicksendE164(phone) {
  const raw = String(phone || '').trim();
  if (raw.startsWith('+')) return raw;
  const digits = raw.replace(/\D/g, '');
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
  return `+${digits}`;
}
async function sendClickSendSms(to, body) {
  if (!clicksendConfigured()) throw new Error('ClickSend is not configured (CLICKSEND_USERNAME / CLICKSEND_API_KEY).');
  const auth = Buffer.from(`${CLICKSEND_USERNAME}:${CLICKSEND_API_KEY}`).toString('base64');
  const message = { source: 'materialflow', to: clicksendE164(to), body };
  if (CLICKSEND_FROM) message.from = CLICKSEND_FROM;
  const resp = await fetch('https://rest.clicksend.com/v3/sms/send', {
    method: 'POST',
    headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ messages: [message] }),
  });
  let json = null;
  try { json = await resp.json(); } catch (e) { /* no body */ }
  const firstResult = json?.data?.messages?.[0];
  const ok = resp.ok && json && json.response_code === 'SUCCESS' && (!firstResult || firstResult.status !== 'FAILED');
  if (!ok) {
    const detail = firstResult?.status_text || firstResult?.status || json?.response_msg || `HTTP ${resp.status}`;
    throw new Error(`ClickSend send failed: ${detail}`);
  }
  return json;
}
async function broadcastClickSendSms(recipients, body) {
  const results = await Promise.allSettled(recipients.map((r) => sendClickSendSms(r.phone, body)));
  results.forEach((r, i) => { if (r.status === 'rejected') console.error(`ClickSend to ${recipients[i].name} (${recipients[i].phone}) failed:`, r.reason?.message || r.reason); });
  return results;
}

function formatOrderSms(order) {
  const materialCost = Number(order.quantity || 0) * Number(order.price_per_unit || 0);
  const salesTax = order.sales_tax_amount !== undefined && order.sales_tax_amount !== null
    ? Number(order.sales_tax_amount) : materialCost * (Number(order.sales_tax_rate || 0) / 100);
  const total = order.total_amount !== undefined && order.total_amount !== null
    ? Number(order.total_amount) : materialCost + salesTax + Number(order.delivery_fee || 0);
  const orderDate = (order.created_at || '').slice(0, 10) || todayStr();
  const lines = [
    `NEW ORDER - ${order.order_number}`,
    `- Date: ${orderDate}`,
    `- Name: ${order.customer_name}`,
    `- Address: ${order.delivery_address}`,
    `- Material: ${order.material_name}`,
    `- Amount: ${order.quantity} ${order.unit}`,
    `- Total: $${total.toFixed(2)} (incl. $${salesTax.toFixed(2)} sales tax)`,
  ];
  if (order.customer_phone) lines.push(`- Phone: ${order.customer_phone}`);
  if (order.requested_window === 'ASAP') lines.push('- Requested: ASAP');
  else if (order.requested_date) lines.push(`- Requested: ${order.requested_date}${order.requested_window ? ' ' + order.requested_window : ''}`);
  if (order.deliveries && order.deliveries.length > 1) {
    lines.push(`- Split into ${order.deliveries.length} truckloads (${MAX_YARDS_PER_DELIVERY}yd max each):`);
    order.deliveries.forEach((d) => {
      lines.push(`  ${d.sequence}) ${d.quantity} ${order.unit} — ${d.driver_name ? d.driver_name : 'unassigned'}${d.scheduled_date ? ' on ' + d.scheduled_date : ''}`);
    });
  } else if (order.driver_name) {
    lines.push(`- Driver: ${order.driver_name}${order.scheduled_date ? ' on ' + order.scheduled_date : ''}`);
  }
  if (order.delivery_fee) lines.push(`- Delivery fee: $${Number(order.delivery_fee).toFixed(2)}${order.distance_miles ? ` (${order.distance_miles} mi)` : ''}`);
  if (order.notes) lines.push(`- Notes: ${order.notes}`);
  return lines.join('\n');
}
async function notifyNewOrder(order) {
  try {
    const recipients = all('SELECT * FROM sms_recipients WHERE active = 1');
    if (!recipients.length) return;
    const body = formatOrderSms(order);
    if (clicksendConfigured()) {
      await broadcastClickSendSms(recipients, body);
    } else if (twilioConfigured()) {
      await broadcastSms(recipients, body);
    } else if (emailSmsConfigured()) {
      await sendEmailSms(recipients, `New Order ${order.order_number}`, body);
    }
  } catch (e) { console.error('notifyNewOrder failed:', e && e.stack ? e.stack : e); }
}

