const routes = [];

// ---- Audit log -------------------------------------------------------
function clientIp(req) {
  const fwd = req.headers['x-forwarded-for'];
  if (fwd) return String(fwd).split(',')[0].trim();
  return (req.socket && req.socket.remoteAddress) || '';
}
function recordAudit(req, opts) {
  const {
    role = null, name = null, userId = null, driverId = null, superAdmin = false,
    action, method, path, status = null, detail = null,
  } = opts || {};
  try {
    run(
      `INSERT INTO audit_log (actor_role, actor_name, actor_user_id, actor_driver_id, is_super_admin, action, method, path, status, detail, ip)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [role, name, userId || null, driverId || null, superAdmin ? 1 : 0, action, method, path, status, detail, clientIp(req)]
    );
  } catch (e) {
    console.error('audit log write failed:', e && e.stack ? e.stack : e);
  }
}
const AUDIT_SELF_LOGGED = new Set(['/api/login', '/api/logout']);

function on(method, pattern, handler) {
  const paramNames = [];
  const regexStr = pattern.replace(/:([A-Za-z]+)/g, (_, name) => { paramNames.push(name); return '([^/]+)'; });
  const autoLog = method !== 'GET' && !AUDIT_SELF_LOGGED.has(pattern);
  const wrapped = !autoLog ? handler : async (req, res, params, query) => {
    await handler(req, res, params, query);
    const session = getSession(req);
    recordAudit(req, {
      role: session && session.role,
      name: session && session.name,
      userId: session && session.userId,
      driverId: session && session.driverId,
      superAdmin: isSuperAdmin(session),
      action: 'request',
      method,
      path: req.url.split('?')[0],
      status: res.statusCode,
    });
  };
  routes.push({ method, regex: new RegExp(`^${regexStr}$`), paramNames, handler: wrapped });
}

function requireAuth(req, res) {
  const session = getSession(req);
  if (!session) { sendJson(res, 401, { error: 'Not logged in' }); return null; }
  return session;
}
function requireOffice(req, res) {
  const session = requireAuth(req, res);
  if (!session) return null;
  if (session.role !== 'office') { sendJson(res, 403, { error: 'Office access required' }); return null; }
  return session;
}

function isSuperAdmin(session) {
  return !!(session && session.role === 'office' && !session.userId);
}

function getAccess(session) {
  if (!session || session.role !== 'office') return null;
  if (!session.userId) return { full: true };
  const user = get('SELECT access_level, can_view_financials, can_view_assets, can_view_realestate, can_access_admin FROM users WHERE id = ?', [session.userId]);
  if (!user || user.access_level === 'full') return { full: true };
  return {
    full: false,
    can_view_financials: !!user.can_view_financials,
    can_view_assets: !!user.can_view_assets,
    can_view_realestate: !!user.can_view_realestate,
    can_access_admin: !!user.can_access_admin,
  };
}

function requireSection(req, res, flag) {
  const session = requireOffice(req, res);
  if (!session) return null;
  const access = getAccess(session);
  if (access.full || access[flag]) return session;
  sendJson(res, 403, { error: "You don't have permission to access this." });
  return null;
}

function requireSuperAdmin(req, res) {
  const session = requireOffice(req, res);
  if (!session) return null;
  if (isSuperAdmin(session)) return session;
  sendJson(res, 403, { error: 'Only the main office account can do this.' });
  return null;
}

const ORDER_SELECT = `
  SELECT o.*, c.name as customer_name, c.phone as customer_phone, c.billing_address as customer_address,
         m.name as material_name, d.name as driver_name, d.truck_label as driver_truck
  FROM orders o JOIN customers c ON c.id = o.customer_id JOIN materials m ON m.id = o.material_id
  LEFT JOIN drivers d ON d.id = o.driver_id
`;
function nextOrderNumberForDate(date) {
  const prefix = `ORD-${date.getFullYear()}${String(date.getMonth() + 1).padStart(2, '0')}${String(date.getDate()).padStart(2, '0')}`;
  const rows = all('SELECT order_number FROM orders WHERE order_number LIKE ?', [`${prefix}%`]);
  let max = 0;
  rows.forEach((r) => {
    const n = parseInt(r.order_number.slice(prefix.length + 1), 10);
    if (!isNaN(n) && n > max) max = n;
  });
  return `${prefix}-${String(max + 1).padStart(3, '0')}`;
}
function nextOrderNumber() { return nextOrderNumberForDate(new Date()); }
function computeOrderTotals(quantity, pricePerUnit, deliveryFee, taxRatePercent) {
  const materialCost = Number(quantity || 0) * Number(pricePerUnit || 0);
  const rate = Number(taxRatePercent || 0);
  const salesTaxAmount = money(materialCost * (rate / 100));
  const totalAmount = money(materialCost + salesTaxAmount + Number(deliveryFee || 0));
  return { salesTaxRate: rate, salesTaxAmount, totalAmount };
}
function nextInvoiceNumber() {
  const prefix = `INV-${new Date().getFullYear()}`;
  const count = get('SELECT COUNT(*) as c FROM invoices WHERE invoice_number LIKE ?', [`${prefix}%`]).c;
  return `${prefix}-${String(count + 1).padStart(4, '0')}`;
}

// ---- DELIVERY SPLITTING & AUTO-SCHEDULING ---------------------------------
// A delivery is one truckload — max 20 yards. Orders over that get split
// into multiple deliveries, each auto-placed into the earliest open
// (driver, day, hour-slot). Drivers work a 9-hour day => 9 one-hour slots/day.
const MAX_YARDS_PER_DELIVERY = 20;
const SLOTS_PER_DAY = 9;
const WORKDAY_START_HOUR = 8; // slot 0 = 8:00am, for display only

function splitIntoDeliveryChunks(quantity) {
  const qty = Number(quantity || 0);
  if (qty <= 0) return [];
  const count = Math.ceil(qty / MAX_YARDS_PER_DELIVERY);
  const chunks = [];
  let remaining = qty;
  for (let i = 0; i < count; i++) {
    const chunk = i === count - 1 ? money(remaining) : MAX_YARDS_PER_DELIVERY;
    chunks.push(chunk);
    remaining = money(remaining - MAX_YARDS_PER_DELIVERY);
  }
  return chunks;
}
function slotTimeLabel(slotIndex) {
  if (slotIndex === null || slotIndex === undefined) return null;
  const hour = WORKDAY_START_HOUR + Number(slotIndex);
  const period = hour >= 12 ? 'PM' : 'AM';
  const h12 = ((hour + 11) % 12) + 1;
  return `${h12}:00 ${period}`;
}
function addDays(dateStr, days) {
  const d = new Date(`${dateStr}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
function usedSlots(driverId, dateStr) {
  return all(`SELECT slot_index FROM deliveries WHERE driver_id = ? AND scheduled_date = ? AND status != 'cancelled'`, [driverId, dateStr])
    .map((r) => r.slot_index).filter((s) => s !== null && s !== undefined);
}
function autoAssignDelivery(deliveryId, opts) {
  const { startDate, preferredDriverId } = opts || {};
  const drivers = preferredDriverId
    ? [get('SELECT * FROM drivers WHERE id = ? AND active = 1', [preferredDriverId])].filter(Boolean)
    : all('SELECT * FROM drivers WHERE active = 1 ORDER BY id');
  if (!drivers.length) return false;
  let date = startDate || todayStr();
  for (let i = 0; i < 120; i++) {
    for (const d of drivers) {
      const used = usedSlots(d.id, date);
      if (used.length >= SLOTS_PER_DAY) continue;
      const usedSet = new Set(used);
      let openSlot = null;
      for (let s = 0; s < SLOTS_PER_DAY; s++) if (!usedSet.has(s)) { openSlot = s; break; }
      run(`UPDATE deliveries SET driver_id = ?, scheduled_date = ?, slot_index = ?, status = 'scheduled', updated_at = datetime('now') WHERE id = ?`,
        [d.id, date, openSlot, deliveryId]);
      return true;
    }
    date = addDays(date, 1);
  }
  return false;
}
// Splits an order's total dollar amount across its truckload chunks in
// proportion to each chunk's share of the total quantity, so a multi-load
// order's loads each show their own slice instead of the full order total.
// The last chunk absorbs the rounding remainder so the loads sum exactly to
// totalAmount.
function splitAmountByChunks(chunks, totalAmount) {
  const totalQty = chunks.reduce((s, q) => s + q, 0) || 1;
  let assigned = 0;
  return chunks.map((qty, idx) => {
    if (idx === chunks.length - 1) return money(totalAmount - assigned);
    const amt = money(totalAmount * (qty / totalQty));
    assigned += amt;
    return amt;
  });
}
function generateDeliveriesForOrder(order, opts) {
  const { preferredDriverId, startDate } = opts || {};
  const chunks = splitIntoDeliveryChunks(order.quantity);
  const amounts = splitAmountByChunks(chunks, order.total_amount || 0);
  chunks.forEach((qty, idx) => {
    const result = run(`INSERT INTO deliveries (order_id, sequence, quantity, amount, status) VALUES (?, ?, ?, ?, 'unscheduled')`, [order.id, idx + 1, qty, amounts[idx]]);
    autoAssignDelivery(result.lastInsertRowid, { startDate, preferredDriverId });
  });
}
function recomputeOrderRollup(orderId) {
  const order = get('SELECT * FROM orders WHERE id = ?', [orderId]);
  if (!order || order.status === 'invoiced') return;
  const deliveries = all('SELECT * FROM deliveries WHERE order_id = ? ORDER BY sequence', [orderId]);
  const notCancelled = deliveries.filter((d) => d.status !== 'cancelled');
  let status;
  let deliveredAt = order.delivered_at;
  if (!notCancelled.length) {
    status = deliveries.length ? 'cancelled' : 'new';
  } else if (notCancelled.every((d) => d.status === 'refused')) {
    status = 'refused';
  } else {
    const active = notCancelled.filter((d) => d.status !== 'refused');
    if (active.every((d) => d.status === 'delivered')) {
      status = 'delivered';
      const dates = active.map((d) => d.delivered_at).filter(Boolean).sort();
      if (dates.length) deliveredAt = dates[dates.length - 1];
    } else if (active.some((d) => d.driver_id && d.scheduled_date)) {
      status = 'scheduled';
    } else {
      status = 'new';
    }
  }
  const scheduledOnes = notCancelled.filter((d) => d.status !== 'refused' && d.driver_id && d.scheduled_date)
    .sort((a, b) => (a.scheduled_date === b.scheduled_date ? a.sequence - b.sequence : (a.scheduled_date < b.scheduled_date ? -1 : 1)));
  const driverId = scheduledOnes.length ? scheduledOnes[0].driver_id : null;
  const scheduledDate = scheduledOnes.length ? scheduledOnes[0].scheduled_date : null;
  run(`UPDATE orders SET status = ?, driver_id = ?, scheduled_date = ?, delivered_at = ?, updated_at = datetime('now') WHERE id = ?`,
    [status, driverId, scheduledDate, deliveredAt, orderId]);
}
function revertDeliveryToScheduled(deliveryId) {
  const d = get('SELECT * FROM deliveries WHERE id = ?', [deliveryId]);
  if (!d) return;
  const newStatus = (d.driver_id && d.scheduled_date) ? 'scheduled' : 'unscheduled';
  run(`UPDATE deliveries SET status = ?, delivered_at = NULL, updated_at = datetime('now') WHERE id = ?`, [newStatus, deliveryId]);
}
function appendDriverNote(orderId, note) {
  if (!note) return;
  const order = get('SELECT driver_notes FROM orders WHERE id = ?', [orderId]);
  const combined = order && order.driver_notes ? `${order.driver_notes}\n${note}` : note;
  run(`UPDATE orders SET driver_notes = ?, updated_at = datetime('now') WHERE id = ?`, [combined, orderId]);
}

// ---- AUTH ----
on('POST', '/api/login', async (req, res) => {
  const body = await readJsonBody(req);
  if (body.role === 'office') {
    const username = (body.username || '').trim().toLowerCase();
    if (username) {
      const user = get('SELECT * FROM users WHERE username = ? AND active = 1', [username]);
      if (user && verifyPassword(body.password || '', user.password_hash, user.password_salt)) {
        createSession(res, { role: 'office', name: user.name, userId: user.id });
        recordAudit(req, { role: 'office', name: user.name, userId: user.id, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: `Logged in as ${user.name}` });
        return sendJson(res, 200, { ok: true, role: 'office', name: user.name });
      }
      recordAudit(req, { role: 'office', name: username, action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: `Failed office login for username "${username}"` });
      return sendJson(res, 401, { error: 'Incorrect username or password' });
    }
    if (body.password === OFFICE_PASSWORD) {
      createSession(res, { role: 'office', name: 'Dispatch' });
      recordAudit(req, { role: 'office', name: 'Dispatch', superAdmin: true, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: 'Logged in as the main office account' });
      return sendJson(res, 200, { ok: true, role: 'office', name: 'Dispatch' });
    }
    recordAudit(req, { role: 'office', action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: 'Failed main office login attempt (wrong password)' });
    return sendJson(res, 401, { error: 'Incorrect password' });
  }
  if (body.role === 'driver') {
    if (!body.driverId) return sendJson(res, 400, { error: 'Pick a driver.' });
    const driver = get('SELECT * FROM drivers WHERE id = ? AND active = 1', [body.driverId]);
    if (driver && driver.pin === String(body.pin || '')) {
      createSession(res, { role: 'driver', driverId: driver.id, name: driver.name });
      recordAudit(req, { role: 'driver', name: driver.name, driverId: driver.id, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: `Driver logged in: ${driver.name}` });
      return sendJson(res, 200, { ok: true, role: 'driver', name: driver.name, driverId: driver.id });
    }
    recordAudit(req, { role: 'driver', name: driver ? driver.name : null, driverId: body.driverId, action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: 'Failed driver login attempt (wrong PIN)' });
    return sendJson(res, 401, { error: 'Incorrect PIN' });
  }
  recordAudit(req, { action: 'login_failed', method: 'POST', path: '/api/login', status: 400, detail: `Unknown login role "${body.role}"` });
  return sendJson(res, 400, { error: 'Unknown role' });
});
on('POST', '/api/logout', async (req, res) => {
  const session = getSession(req);
  if (session) {
    recordAudit(req, {
      role: session.role, name: session.name, userId: session.userId, driverId: session.driverId,
      superAdmin: isSuperAdmin(session), action: 'logout', method: 'POST', path: '/api/logout', status: 200, detail: 'Logged out',
    });
  }
  destroySession(req, res);
  sendJson(res, 200, { ok: true });
});
on('GET', '/api/me', async (req, res) => { const session = getSession(req); if (!session) return sendJson(res, 200, { loggedIn: false }); const access = getAccess(session); sendJson(res, 200, { loggedIn: true, ...session, access, isSuperAdmin: isSuperAdmin(session) }); });
on('GET', '/api/audit-log', async (req, res, params, query) => {
  if (!requireSuperAdmin(req, res)) return;
  const limit = Math.min(Number(query.limit) || 100, 500);
  const offset = Math.max(Number(query.offset) || 0, 0);
  const conditions = [];
  const args = [];
  if (query.who === 'super_admin') { conditions.push("actor_role = 'office' AND is_super_admin = 1"); }
  else if (query.who === 'named_user') { conditions.push("actor_role = 'office' AND is_super_admin = 0"); }
  else if (query.who === 'driver') { conditions.push("actor_role = 'driver'"); }
  if (query.action) { conditions.push('action = ?'); args.push(query.action); }
  if (query.q) {
    const like = `%${query.q}%`;
    conditions.push('(actor_name LIKE ? OR path LIKE ? OR detail LIKE ?)');
    args.push(like, like, like);
  }
  const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  const rows = all(`SELECT * FROM audit_log ${where} ORDER BY id DESC LIMIT ? OFFSET ?`, [...args, limit, offset]);
  rows.forEach((r) => { r.created_at_display = formatEasternDateTime(r.created_at); });
  const total = get(`SELECT COUNT(*) as count FROM audit_log ${where}`, args).count;
  sendJson(res, 200, { rows, total });
});

// ---- FORGOT / RESET PASSWORD ----
const RESET_TOKEN_TTL_MS = 60 * 60 * 1000;
function hashResetToken(token) { return crypto.createHash('sha256').update(token).digest('hex'); }
on('POST', '/api/forgot-password', async (req, res) => {
  const b = await readJsonBody(req);
  const username = (b.username || '').trim().toLowerCase();
  const genericMsg = { ok: true, message: 'If that account exists and has an email on file, a reset link has been sent.' };
  if (!username) return sendJson(res, 200, genericMsg);
  const user = get('SELECT * FROM users WHERE username = ? AND active = 1', [username]);
  if (user && user.email && emailConfigured()) {
    const token = crypto.randomBytes(32).toString('hex');
    const expires = new Date(Date.now() + RESET_TOKEN_TTL_MS).toISOString();
    run('UPDATE users SET reset_token_hash = ?, reset_token_expires = ? WHERE id = ?', [hashResetToken(token), expires, user.id]);
    const baseUrl = `${req.headers['x-forwarded-proto'] || 'http'}://${req.headers.host}`;
    try {
      await sendMail({
        to: user.email,
        subject: 'Reset your OPD Development Corp password',
        text: `Hi ${user.name},\n\nSomeone requested a password reset for your account (${user.username}).\n\nReset your password here (link expires in 1 hour):\n${baseUrl}/reset-password.html?token=${token}\n\nIf you didn't request this, you can safely ignore this email — your password will stay the same.`,
      });
    } catch (err) {}
  }
  sendJson(res, 200, genericMsg);
});
on('POST', '/api/reset-password', async (req, res) => {
  const b = await readJsonBody(req);
  const token = (b.token || '').trim();
  const password = b.password || '';
  if (!token) return sendJson(res, 400, { error: 'Missing reset token.' });
  if (password.length < 6) return sendJson(res, 400, { error: 'Password must be at least 6 characters' });
  const tokenHash = hashResetToken(token);
  const user = get('SELECT * FROM users WHERE reset_token_hash = ? AND active = 1', [tokenHash]);
  if (!user || !user.reset_token_expires || new Date(user.reset_token_expires).getTime() < Date.now()) {
    return sendJson(res, 400, { error: 'This reset link is invalid or has expired. Request a new one.' });
  }
  const { hash, salt } = hashPassword(password);
  run('UPDATE users SET password_hash = ?, password_salt = ?, reset_token_hash = NULL, reset_token_expires = NULL WHERE id = ?',
    [hash, salt, user.id]);
  sendJson(res, 200, { ok: true });
});

