// ---- USER ACCOUNTS (named office logins — username + password) -----------
const USER_SELECT = 'SELECT id, name, username, email, active, access_level, can_view_financials, can_view_assets, can_view_realestate, can_access_admin, created_at FROM users ORDER BY name';

function accessFieldsFromBody(b, existing) {
  const access_level = b.access_level === 'limited' ? 'limited' : (b.access_level === 'full' ? 'full' : (existing ? existing.access_level : 'full'));
  const flag = (key) => b[key] !== undefined ? (b[key] ? 1 : 0) : (existing ? existing[key] : 0);
  return {
    access_level,
    can_view_financials: flag('can_view_financials'),
    can_view_assets: flag('can_view_assets'),
    can_view_realestate: flag('can_view_realestate'),
    can_access_admin: flag('can_access_admin'),
  };
}

on('GET', '/api/users', async (req, res) => { if (!requireSuperAdmin(req, res)) return; sendJson(res, 200, all(USER_SELECT)); });
on('POST', '/api/users', async (req, res) => {
  if (!requireSuperAdmin(req, res)) return;
  const b = await readJsonBody(req);
  const name = (b.name || '').trim();
  const username = (b.username || '').trim().toLowerCase();
  const password = b.password || '';
  if (!name || !username || !password) return sendJson(res, 400, { error: 'Name, username, and password are required' });
  if (password.length < 6) return sendJson(res, 400, { error: 'Password must be at least 6 characters' });
  const clash = get('SELECT id FROM users WHERE username = ?', [username]);
  if (clash) return sendJson(res, 400, { error: 'That username is already taken' });
  const email_ = (b.email || '').trim().toLowerCase() || null;
  const { hash, salt } = hashPassword(password);
  const acc = accessFieldsFromBody(b, null);
  const result = run(`INSERT INTO users
    (name, username, email, password_hash, password_salt, access_level, can_view_financials, can_view_assets, can_view_realestate, can_access_admin)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [name, username, email_, hash, salt, acc.access_level, acc.can_view_financials, acc.can_view_assets, acc.can_view_realestate, acc.can_access_admin]);
  sendJson(res, 201, get(USER_SELECT.replace('ORDER BY name', 'WHERE id = ?'), [result.lastInsertRowid]));
});
on('PUT', '/api/users/:id', async (req, res, params) => {
  if (!requireSuperAdmin(req, res)) return;
  const b = await readJsonBody(req);
  const existing = get('SELECT * FROM users WHERE id = ?', [params.id]);
  if (!existing) return sendJson(res, 404, { error: 'Account not found' });
  const name = b.name !== undefined && b.name !== '' ? b.name.trim() : existing.name;
  let username = existing.username;
  if (b.username !== undefined && b.username !== '') {
    username = b.username.trim().toLowerCase();
    const clash = get('SELECT id FROM users WHERE username = ? AND id != ?', [username, params.id]);
    if (clash) return sendJson(res, 400, { error: 'That username is already taken' });
  }
  const active = b.active !== undefined ? (b.active ? 1 : 0) : existing.active;
  const email_ = b.email !== undefined ? ((b.email || '').trim().toLowerCase() || null) : existing.email;
  let password_hash = existing.password_hash;
  let password_salt = existing.password_salt;
  if (b.password) {
    if (b.password.length < 6) return sendJson(res, 400, { error: 'Password must be at least 6 characters' });
    const { hash, salt } = hashPassword(b.password);
    password_hash = hash;
    password_salt = salt;
  }
  const acc = accessFieldsFromBody(b, existing);
  run(`UPDATE users SET name = ?, username = ?, email = ?, active = ?, password_hash = ?, password_salt = ?,
    access_level = ?, can_view_financials = ?, can_view_assets = ?, can_view_realestate = ?, can_access_admin = ? WHERE id = ?`,
    [name, username, email_, active, password_hash, password_salt,
      acc.access_level, acc.can_view_financials, acc.can_view_assets, acc.can_view_realestate, acc.can_access_admin, params.id]);
  sendJson(res, 200, get(USER_SELECT.replace('ORDER BY name', 'WHERE id = ?'), [params.id]));
});
on('DELETE', '/api/users/:id', async (req, res, params) => {
  if (!requireSuperAdmin(req, res)) return;
  run('DELETE FROM users WHERE id = ?', [params.id]);
  sendJson(res, 200, { ok: true });
});

