// Deliberately separate from the `equipment` table used by the Jobs module
// for crew/equipment scheduling — this is financial record-keeping, not
// operational scheduling, and the two are not merged or synced.

on('GET', '/api/assets', async (req, res, params, query) => {
  if (!requireSection(req, res, 'can_view_assets')) return;
  const showAll = query && query.all === '1';
  sendJson(res, 200, showAll
    ? all('SELECT * FROM assets ORDER BY category, name')
    : all('SELECT * FROM assets WHERE active = 1 ORDER BY category, name'));
});

on('GET', '/api/assets/summary', async (req, res) => {
  if (!requireSection(req, res, 'can_view_assets')) return;
  const rows = all('SELECT category, estimated_value, debt_balance FROM assets WHERE active = 1');
  const totalValue = money(rows.reduce((sum, r) => sum + (r.estimated_value || 0), 0));
  const totalDebt = money(rows.reduce((sum, r) => sum + (r.debt_balance || 0), 0));
  const byCategory = {};
  rows.forEach((r) => {
    const cat = r.category || 'other';
    if (!byCategory[cat]) byCategory[cat] = { category: cat, count: 0, value: 0, debt: 0 };
    byCategory[cat].count += 1;
    byCategory[cat].value += (r.estimated_value || 0);
    byCategory[cat].debt += (r.debt_balance || 0);
  });
  const by_category = Object.values(byCategory)
    .map((c) => ({ category: c.category, count: c.count, value: money(c.value), debt: money(c.debt), equity: money(c.value - c.debt) }))
    .sort((a, b) => b.value - a.value);
  sendJson(res, 200, {
    total_assets: rows.length,
    total_value: totalValue,
    total_debt: totalDebt,
    net_worth: money(totalValue - totalDebt),
    by_category,
  });
});

