on('GET', '/api/properties/summary', async (req, res) => {
  if (!requireSection(req, res, 'can_view_realestate')) return;
  const props = all('SELECT * FROM properties WHERE active = 1');
  const totalValue = money(props.reduce((sum, p) => sum + (p.current_value || 0), 0));
  const totalMortgage = money(props.reduce((sum, p) => sum + (p.mortgage_balance || 0), 0));
  const totalIncome = money((get('SELECT SUM(amount) as t FROM property_income') || {}).t || 0);
  const totalExpenses = money((get('SELECT SUM(amount) as t FROM property_expenses') || {}).t || 0);
  sendJson(res, 200, {
    total_properties: props.length,
    total_value: totalValue,
    total_mortgage_debt: totalMortgage,
    net_equity: money(totalValue - totalMortgage),
    total_income: totalIncome,
    total_expenses: totalExpenses,
    net_cash_flow: money(totalIncome - totalExpenses),
  });
});

on('GET', '/api/properties/:id', async (req, res, params) => {
  if (!requireSection(req, res, 'can_view_realestate')) return;
  const row = get('SELECT * FROM properties WHERE id = ?', [params.id]);
  if (!row) return sendJson(res, 404, { error: 'Property not found' });
  const income = all('SELECT * FROM property_income WHERE property_id = ? ORDER BY date DESC, id DESC', [params.id]);
  const expenses = all('SELECT * FROM property_expenses WHERE property_id = ? ORDER BY date DESC, id DESC', [params.id]);
  const totalIncome = money(income.reduce((s, r) => s + (r.amount || 0), 0));
  const totalExpenses = money(expenses.reduce((s, r) => s + (r.amount || 0), 0));
  sendJson(res, 200, { ...row, income, expenses, total_income: totalIncome, total_expenses: totalExpenses, net_cash_flow: money(totalIncome - totalExpenses) });
});

