// Lets a driver undo their own accidental "Start Delivery" tap. Deliberately
// narrower than office's /revert below — this only steps out_for_delivery
// back to scheduled, never delivered/refused/cancelled, so undoing a
// completed or cancelled load still needs office's second set of eyes.
on('POST', '/api/deliveries/:id/undo-start', async (req, res, params) => {
  const session = requireAuth(req, res); if (!session) return;
  const existing = get('SELECT * FROM deliveries WHERE id = ?', [params.id]);
  if (!existing) return sendJson(res, 404, { error: 'Delivery not found' });
  if (session.role === 'driver' && existing.driver_id !== session.driverId) return sendJson(res, 403, { error: 'Not your delivery' });
  if (existing.status !== 'out_for_delivery') return sendJson(res, 400, { error: 'Only a delivery that has been started can be undone this way.' });
  run(`UPDATE deliveries SET status = 'scheduled', updated_at = datetime('now') WHERE id = ?`, [params.id]);
  recomputeOrderRollup(existing.order_id);
  sendJson(res, 200, get(`${DELIVERY_SELECT} WHERE del.id = ?`, [params.id]));
});
