// Driver-collected ("COD") payment recorded against THIS LOAD — scoped
// per-delivery (not per-order) so a multi-load order can have each load
// paid separately, by different methods/amounts/times.
on('POST', '/api/deliveries/:id/mark-paid', async (req, res, params) => {
  const session = requireAuth(req, res); if (!session) return;
  const existing = get('SELECT * FROM deliveries WHERE id = ?', [params.id]);
  if (!existing) return sendJson(res, 404, { error: 'Delivery not found' });
  if (session.role === 'driver' && existing.driver_id !== session.driverId) return sendJson(res, 403, { error: 'Not your delivery' });
  const b = await readJsonBody(req);
  const amount = b.amount !== undefined && b.amount !== '' && b.amount !== null ? money(b.amount) : money(existing.amount || 0);
  const method = ['cash', 'check', 'other'].includes(b.method) ? b.method : 'other';
  run(`UPDATE deliveries SET payment_collected = 1, payment_collected_method = ?, payment_collected_amount = ?, payment_collected_at = datetime('now'), updated_at = datetime('now') WHERE id = ?`, [method, amount, params.id]);
  sendJson(res, 200, get(`${DELIVERY_SELECT} WHERE del.id = ?`, [params.id]));
});
on('POST', '/api/orders/:id/email-invoice', async (req, res, params) => {
  const session = requireAuth(req, res); if (!session) return;
  const order = get(`${ORDER_SELECT} WHERE o.id = ?`, [params.id]);
  if (!order) return sendJson(res, 404, { error: 'Order not found' });
  if (session.role === 'driver') {
    const owns = get('SELECT id FROM deliveries WHERE order_id = ? AND driver_id = ?', [params.id, session.driverId]);
    if (!owns) return sendJson(res, 403, { error: 'Not your delivery' });
  }
  const customer = get('SELECT * FROM customers WHERE id = ?', [order.customer_id]);
  if (!customer || !customer.email) return sendJson(res, 400, { error: 'This customer has no email address on file.' });
  if (!emailConfigured()) return sendJson(res, 400, { error: 'Email is not configured yet (SMTP_USER / SMTP_PASS on the server).' });
  try {
    // Payment is tracked per-load now — roll this order's loads back up into
    // one summary so the single-order invoice PDF still shows whether (and
    // how much of) it has been paid.
    const paySummary = orderPaymentSummary(order.id);
    const orderForPdf = { ...order, payment_collected: paySummary.collected ? 1 : 0, payment_collected_amount: paySummary.amount, payment_collected_method: paySummary.method };
    const pdfBuffer = buildOrderInvoicePdf(orderForPdf, customer);
    await sendMail({
      to: customer.email,
      subject: `Invoice for Order ${order.order_number} — OPD Development Corp`,
      text: `Hi ${customer.name},\n\nAttached is the invoice for your recent delivery (Order ${order.order_number}).\n\nTotal due: $${Number(order.total_amount || 0).toFixed(2)}\n\nThank you for your business!\nOPD Development Corp`,
      attachments: [{ filename: `Invoice-${order.order_number}.pdf`, content: pdfBuffer, contentType: 'application/pdf' }],
    });
    sendJson(res, 200, { ok: true, sentTo: customer.email });
  } catch (e) {
    sendJson(res, 500, { error: e.message });
  }
});

// ---- DRIVER TIME CLOCK ----

// A shift's stats: hours worked, loads delivered, and payments collected
// during the shift window — driven entirely by timestamps (delivered_at /
// payment_collected_at falling between clock_in and clock_out, or "now" if
// the shift is still open), so it's accurate regardless of which calendar
// date the shift technically started or ended on.
function computeShiftStats(shift) {
  const deliveries = all(
    `SELECT del.*, o.order_number, c.name as customer_name, m.name as material_name, o.unit
     FROM deliveries del
     JOIN orders o ON o.id = del.order_id
     JOIN customers c ON c.id = o.customer_id
     JOIN materials m ON m.id = o.material_id
     WHERE del.driver_id = ? AND del.status = 'delivered'
       AND del.delivered_at BETWEEN ? AND COALESCE(?, datetime('now'))
     ORDER BY del.delivered_at`,
    [shift.driver_id, shift.clock_in, shift.clock_out]
  );
  const paidLoads = all(
    `SELECT del.*, o.order_number, c.name as customer_name
     FROM deliveries del
     JOIN orders o ON o.id = del.order_id
     JOIN customers c ON c.id = o.customer_id
     WHERE del.driver_id = ? AND del.payment_collected = 1
       AND del.payment_collected_at BETWEEN ? AND COALESCE(?, datetime('now'))
     ORDER BY del.payment_collected_at`,
    [shift.driver_id, shift.clock_in, shift.clock_out]
  );
  const totals = { cash: 0, check: 0, other: 0 };
  paidLoads.forEach((p) => {
    const method = ['cash', 'check', 'other'].includes(p.payment_collected_method) ? p.payment_collected_method : 'other';
    totals[method] += Number(p.payment_collected_amount || 0);
  });
  const hoursRow = get(
    `SELECT (julianday(COALESCE(?, datetime('now'))) - julianday(?)) * 24 as hours`,
    [shift.clock_out, shift.clock_in]
  );
  return {
    deliveries,
    paidLoads,
    deliveredCount: deliveries.length,
    totalQuantity: deliveries.reduce((s, d) => s + Number(d.quantity || 0), 0),
    cashTotal: money(totals.cash),
    checkTotal: money(totals.check),
    otherTotal: money(totals.other),
    grandCollected: money(totals.cash + totals.check + totals.other),
    hours: Math.max(0, Math.round((hoursRow.hours || 0) * 100) / 100),
  };
}

