on('GET', '/api/driver/shifts', async (req, res, params, query) => {
  if (!requireOffice(req, res)) return;
  const clauses = [];
  const args = [];
  if (query.driver_id) { clauses.push('s.driver_id = ?'); args.push(query.driver_id); }
  if (query.date) { clauses.push(`date(s.clock_in) = ?`); args.push(query.date); }
  const where = clauses.length ? `WHERE ${clauses.join(' AND ')}` : '';
  const shifts = all(
    `SELECT s.*, d.name as driver_name FROM driver_shifts s JOIN drivers d ON d.id = s.driver_id ${where} ORDER BY s.clock_in DESC LIMIT 200`,
    args
  );
  sendJson(res, 200, shifts.map((s) => ({ ...s, stats: computeShiftStats(s) })));
});

